var player=UnityEngine.Object.FindFirstObjectByType<Poolcore.FirstPersonController>();var menu=UnityEngine.Object.FindFirstObjectByType<Poolcore.ExperienceMenu>();if(menu)menu.BeginAutomatedTest();var report=new System.Text.StringBuilder();int failures=0;
try{player.Teleport(new UnityEngine.Vector3(42.3f,.05f,16));player.transform.rotation=UnityEngine.Quaternion.identity;var route=new[]{new UnityEngine.Vector2(42.3f,22),new UnityEngine.Vector2(39,22),new UnityEngine.Vector2(36,22),new UnityEngine.Vector2(36,20),new UnityEngine.Vector2(36,24),new UnityEngine.Vector2(39,24),new UnityEngine.Vector2(39,28),new UnityEngine.Vector2(42.3f,28),new UnityEngine.Vector2(42.3f,16)};
foreach(var target in route){int steps=0;var delta=target-new UnityEngine.Vector2(player.transform.position.x,player.transform.position.z);while(delta.magnitude>.12f&&steps++<1800){player.SimulateMovement(delta.normalized,false,1f/60);delta=target-new UnityEngine.Vector2(player.transform.position.x,player.transform.position.z);}bool pass=delta.magnitude<=.12f;if(!pass)failures++;report.AppendLine((pass?"PASS":"FAIL")+" "+target+" at "+player.transform.position);}}
finally{player.ResetToSpawn();}
report.AppendLine("Failures: "+failures);System.IO.File.WriteAllText("artifacts/hall-finish/recess-route.txt",report.ToString());return report.ToString();
